// One-hot encoded Mealy finite-state machine. Same functionality as the 2's
// complementer. Reset is active-high, asynchronous, and goes to state A
// immediately.
module TopModule(input clk, input areset, input x, output reg z);
  reg [1:0] state, next_state;
  always @(*) begin
    case (state)
      2'b00: begin z = 1'b0; if (x) next_state = 2'b01; else next_state = 2'b00; end
      2'b01: begin z = 1'b1; if (x) next_state = 2'b11; else next_state = 2'b01; end
      2'b10: begin z = 1'b1; if (x) next_state = 2'b11; else next_state = 2'b10; end
      2'b11: begin z = 1'b0; if (x) next_state = 2'b01; else next_state = 2'b11; end
    endcase
  end
  always @(posedge clk) begin
    if (areset) state <= 2'b00;
    else state <= next_state;
  end
endmodule

